var app = new Vue({
    el: '#app',
    delimiters: ['[[', ']]'],
    data: {
        
    },
    methods: {
        clearCache() {
            const path = window.location.href;
            axios.delete(path)
                .then((response) => {
                    this.$notify({
                        group: 'notification',
                        type: response.data["status"],
                        title: response.data["title"],
                        text: response.data["message"],
                        duration: 2500,
                        speed: 1000
                    })
                })
                .catch((error) => {
                    console.log(error);
                });
        }
    }
})